window.LIT_VERSES={"mutanabbi-azm-001":{"id":"mutanabbi-azm-001","poemId":"ala-qadr-ahl-al-azm","order":1,"first":"عَلى قَدرِ أَهلِ العَزمِ تَأتي العَزائِمُ","second":"وَتَأتي عَلى قَدرِ الكِرامِ المَكارِمُ","meaning":"يجعل المتنبي مقدار الفعل تابعًا لمقدار صاحبه: فكلما عظمت الهمة عظمت الأمور التي يعزم صاحبها عليها، وكلما عظم كرم الإنسان عظمت مكارمه. البيت ليس حكمة مستقلة فحسب؛ بل قاعدة سيبني عليها مدح سيف الدولة في الأبيات التالية.","vocabulary":[{"term":"العزم","text":"قوة القصد والثبات على الأمر."},{"term":"العزائم","text":"الأمور التي يُعزم عليها؛ أي الأعمال والمقاصد الكبيرة."},{"term":"المكارم","text":"الأفعال والخصال التي يظهر بها الكرم والفضل."}],"syntax":["تقدّم شبه الجملة «على قدر أهل العزم» على الفعل «تأتي»، فصار معيار التناسب أول ما تستقبله الأذن.","البناء النحوي في الشطرين متوازٍ: شبه جملة + فعل + فاعل، مع إعادة ترتيب يسيرة في الشطر الثاني تمنع الرتابة وتحفظ التوازي.","«العزائم» و«المكارم» فاعلان للفعل «تأتي»، وفي الإسناد حركة تجعل المعاني المجردة كأنها أشياء تقبل بحسب أقدار أصحابها."],"morphology":["«العزائم» جمع «عزيمة»، وهي من مادة عزم؛ فالجمع يعيد معنى العزم في صورة الأعمال والقرارات التي تصدر عنه.","«المكارم» جمع «مكرمة»، من مادة كرم. اقتران «الكرام» بـ«المكارم» اشتقاقيًا يجعل الصفة في أصحابها كأنها تفيض إلى أفعالهم.","تجاور مادتي «عزم» و«كرم» في صيغ متقاربة جزء من إحكام البيت، وليس مجرد تشابه صوتي."],"rhetoric":{"thesis":"بلاغة البيت في أنه يحول المديح من ادعاء مباشر إلى قاعدة تبدو عامة ومحكمة، ثم يترك الأبيات التالية تثبت أن سيف الدولة هو المثال الذي تنطبق عليه.","devices":[{"title":"التقديم وبناء المعيار","text":"افتتاح الشطر بـ«على قدر» يضع فكرة القياس والتناسب في المركز. لو قيل «تأتي العزائم على قدر أهل العزم» لبقي المعنى، لكن قوة الافتتاح بوصفه قاعدة ستضعف."},{"title":"الموازنة التركيبية","text":"«أهل العزم / العزائم» تقابلها «الكرام / المكارم». التوازي لا يزين الصوت فقط؛ بل يوحي بأننا أمام قانون له صورتان تؤكد إحداهما الأخرى."},{"title":"الاشتقاق ووحدة الفكرة","text":"التقارب بين «العزم / العزائم» وبين «الكرام / المكارم» يجعل الصفة وأثرها متجاورين لفظًا ومعنى؛ كأن العزيمة ثمرة العزم، والمكرمة ثمرة الكرم."},{"title":"صيغة الحكمة","text":"لا يذكر سيف الدولة بعد. هذا التأخير مقصود بنائيًا: يثبت المعيار أولًا، ثم يقدّم الممدوح في البيت الثالث بوصفه برهانًا حيًا عليه."}],"connection":"البيت الثاني سيضيف عنصرًا آخر إلى هذه القاعدة: ليست عظمة الفعل وحدها مرتبطة بعظمة صاحبه، بل حتى تقدير الأفعال يتغير باختلاف قدر الناظر إليها."},"prosody":{"meter":"البحر الطويل","rhyme":"الروي ميم مضمومة","note":"الإيقاع الطويل المسترسل يلائم افتتاحًا تقريريا ذا نبرة عالية، بينما تكرار البنية النحوية داخل البيت يمنحه تماسكًا أشبه بصياغة المثل."},"context":"مطلع القصيدة. وظيفته تأسيس المعيار الذي ستُقاس به أفعال سيف الدولة في وقعة الحدث.","sourceIds":["wahidi-274","barquqi-162-170"]},"mutanabbi-azm-002":{"id":"mutanabbi-azm-002","poemId":"ala-qadr-ahl-al-azm","order":2,"first":"وَتَعظُمُ في عَينِ الصَغيرِ صِغارُها","second":"وَتَصغُرُ في عَينِ العَظيمِ العَظائِمُ","meaning":"الأمور الصغيرة تبدو كبيرة لمن صغر قدره وهمته، بينما يرى العظيم الأعمال العظيمة دون مستوى ما يستطيع الإقدام عليه. المتنبي ينقلنا من مقدار الفعل في نفسه إلى مقدار الفعل في عين من يقدّره.","vocabulary":[{"term":"الصغير","text":"ليس المراد صغر السن، بل صغر القدر والهمة في سياق البيت."},{"term":"العظيم","text":"عظيم القدر والهمة."},{"term":"صغارها / العظائم","text":"صغار الأمور وعظائمها، والضمير عائد إلى الأعمال والأحوال المفهومة من السياق."}],"syntax":["«صغارها» فاعل «تعظم» مؤخر، و«العظائم» فاعل «تصغر» مؤخر؛ تقديم الفعل يجعل التحول في الرؤية هو بداية كل شطر.","تكرار «في عين» يربط الحكم بزاوية الإدراك لا بحجم الشيء وحده.","الشطران متقابلان نحويًا ودلاليًا: تعظم/تصغر، الصغير/العظيم، صغارها/العظائم."],"morphology":["تدور ألفاظ «تعظم، العظيم، العظائم» على مادة عظم، وألفاظ «تصغر، الصغير، صغارها» على مادة صغر؛ وهذا الاشتقاق يبني قطبي البيت من الجذر نفسه.","«العظائم» جمع «عظيمة» بمعنى الأمور الجليلة، و«صغارها» جمع «صغيرة» مضاف إلى الضمير العائد إلى الأمور/الأفعال المفهومة من السياق.","المضارعان «تعظم» و«تصغر» يمنحان الحكم صفة التكرر والاستمرار، فيلائم ذلك صيغة الحكمة العامة."],"rhetoric":{"thesis":"هذا البيت مثال واضح على أن البلاغة ليست مجرد تسمية «طباق». قوته في شبكة كاملة من التقابل والاشتقاق وترتيب الكلمات تجعل الفكرة تُرى وهي تنقلب أمام القارئ.","devices":[{"title":"مقابلة كاملة","text":"«تعظم / تصغر» و«الصغير / العظيم» و«صغارها / العظائم»؛ ثلاث طبقات من التضاد تعمل في وقت واحد، ولذلك يبدو الشطر الثاني كمرآة تقلب الشطر الأول."},{"title":"اشتقاق متكرر","text":"يدور الشطر الأول حول مادة الصغر، والثاني حول مادة العظم، فتتردد الجذور نفسها في الفعل والاسم والصفة. هذا يجعل اللغة نفسها تجسّد عملية التكبير والتصغير."},{"title":"العين بوابة الحكم","text":"لم يقل «عند الصغير» بل «في عين الصغير». ينقل الحكم إلى مشهد الرؤية، فيصبح اختلاف المقادير اختلافًا في البصيرة والقدرة على التقدير."},{"title":"التدرج الحجاجي","text":"بعد أن قرر البيت الأول أن عظمة الفعل تتناسب مع عظمة الفاعل، يقرر هذا البيت أن العظيم نفسه لا يتهيب العظائم. وهكذا يمهد نفسيًا لقول: «يكلف سيف الدولة الجيش همه»."}],"connection":"البيت الثالث سيترك الحكمة العامة لأول مرة ويسمي سيف الدولة مباشرة، فيتحول الكلام من قاعدة إلى تطبيق."},"prosody":{"meter":"البحر الطويل","rhyme":"الروي ميم مضمومة","note":"التناظر الشديد بين الشطرين يصنع إيقاعًا داخليًا فوق إيقاع البحر: تعظم/تصغر، الصغير/العظيم، صغارها/العظائم."},"context":"ثاني مقدمة الحكمة، وهو الجسر الأخير قبل الانتقال إلى الممدوح بالاسم.","sourceIds":["wahidi-274","barquqi-162-170"]}};